featix = find(mask);

if isempty(featix)
    error(['Could not find index for feature: ' featName{1}]);
end

if numel(featix) > 1
    fns = traj{view}(trix).featNames;
    keep = false(size(featix));
    for i = 1:numel(featix)
        if strcmpi(featName,fns{featix(i)})
            keep(i) = true;
        end
    end
    featix = featix(keep);
end



end % findDLCFeatIndex

